insert into public.pub_admin (pub_id, prices_online, notes) values ('the-craft-beer-co-holborn', 'partial', 'Events page: http://www.thecraftbeerco.com/events (weekly quiz Wed 8pm, open mic Fri 7:30pm, tap takeovers). Brands this site as ''Covent Garden'' though it is on High Holborn. ~15 cask + 30 keg lines that rotate constantly, so fixed drink lists go stale fast; Untappd shows the live beer list (prices sometimes). LEAD (review, date unknown): ~£7.70 a pint, specials much more. coventgarden@thecraftbeerco.com, 020 7836 5485.') on conflict (pub_id) do nothing;
