insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, operator) values ('the-punch-and-judy', 'The Punch and Judy', '40 The Market, Covent Garden Piazza, London WC2E 8RF', 'Covent Garden', 51.51187, -0.12319, null, array['outdoor-drinking']::text[], 'A pub inside the old Covent Garden market building. Its balcony looks straight down on the Piazza''s street performers.', 'https://www.greeneking.co.uk/pubs/greater-london/punch-and-judy', 'https://www.greeneking.co.uk/pubs/greater-london/punch-and-judy/menu', 'Greene King') on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), operator = coalesce(public.pubs.operator, excluded.operator);
