insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, operator) values ('the-rocket', 'The Rocket', '120 Euston Road, London NW1 2AL', 'King''s Cross', 51.52808, -0.13052, 1899, array['historic', 'victorian-interior', 'sports-tv', 'food', 'quiz-night', 'live-music', 'dog-friendly']::text[], 'A Grade II listed Victorian corner pub on Euston Road, rebuilt in 1899 for the Cannon Brewery and once called The Rising Sun. Its arched windows wrap around the corner, and it''s handy for Euston, King''s Cross and St Pancras.', 'https://www.therocketeustonroad.co.uk/', 'https://www.therocketeustonroad.co.uk/drinks', 'Mitchells & Butlers') on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), operator = coalesce(public.pubs.operator, excluded.operator);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-rocket', 'yes', '[Sep 2026 research] Added at Archie''s request. Drinks page lists Peroni, BrewDog Punk IPA, Guinness, Magners, Bulmers, Rekorderlig, plus 3 regular cask ales (names not found), but NO PRICES in search results. UPDATE 24 Sep 2026: Archie sent screenshots of the Beer & Cider tab: 15 BOTTLED beers/ciders now have real prices (source: website). UPDATE 2 (24 Sep, 07:24 screenshots of the order-at-table menu): 14 DRAUGHT pints added (e.g. Guinness £6.65, Landlord £6.45, Coors £6.25, Neck Oil £7.90). Bottle sizes taken from it (Newcastle 550ml, Magners 568ml, Thatchers Haze 500ml, Rekorderlig 500ml). PRICE MISMATCH: the order menu lists bottles 15-20p cheaper than the drinks page (Peroni/Corona/Budweiser/Daura £5.85, Modelo £5.90, Desperados £6.10, Schöfferhofer £6.10, Newcastle £5.75, Magners £6.10, Thatchers Haze £6.60, Rekorderlig £6.50). Drinks-page prices kept; check at the bar which is current. Not added: Breezer/WKD/Smirnoff Ice (alcopops), wine. Alpacalypse category unknown (set to Other). Deals: meal + drink from £9.50 Mon-Fri 12-6pm (+£1 for alcohol). Monday quiz night (CAMRA). Sky Sports, food, child and dog friendly, regular live entertainment; inapub mentions a garden: check. CHECK MAP PIN: coordinates are approximate (south side of Euston Road). Formerly The Rising Sun / Friar and Firkin; owners per Wikipedia: Mitchells & Butlers.') on conflict (pub_id) do nothing;
